-- Generado por sync/cajas-datos.mjs el 2026-10-30. No se edita a mano: se vuelve a generar.
-- Fuentes: ByMykel/CSGO-API (cajas, skins, imagenes de Steam) y Skinport (precios en euros). 1 euro = 20 V-Bucks en skins y 1 en lujo.
-- Precio de cada caja: valor medio de lo que sale (probabilidades de TIER_P, desgaste y StatTrak) mas un 0 % (0: devolucion media del 100 %).
-- Se carga despues de 007_cajas.sql y 012_cajas_mas.sql (no hace falta 007b: este lo sustituye; si 007b ya esta cargado, esto lo pone al dia)
-- y se puede cargar otra vez para poner los precios al dia. Las cajas de lujo (cat = 'lujo') salen de sync/lujo-datos.mjs.
-- Precios de cada skin: RF CN AD BD D y despues lo mismo en StatTrak, en V-Bucks.

on conflict (id) do update set name = excluded.name, phase = excluded.phase, rarity = excluded.rarity, image = excluded.image,
  minf = excluded.minf, maxf = excluded.maxf, st = excluded.st, weight = excluded.weight, price = excluded.price;

on conflict (id) do update set name = excluded.name, image = excluded.image, price = excluded.price, ev = excluded.ev,
  sort = excluded.sort, released = excluded.released, active = true, cat = excluded.cat;
